#!/usr/bin/env python3
#
#  Checks the wall shear stress variables of a Tecplot file generated by horses2plt
#  from a surface solution saved with "surface save utau" and
#  "surface save utau vector" (u_tau, u_tau_x/y/z, tau, tau_x/y/z and rho must be exported).
#
#  At every point of the (single) fluid zone:
#     |u_tau_vector|  = u_tau                    (scalar and vector friction velocity agree)
#     tau             = rho * u_tau^2
#     tau_i           = rho * u_tau * u_tau_i     (tau_vector is parallel to u_tau_vector)
#     |tau_vector|    = tau
#
#  Each difference is scaled with the maximum absolute value of the compared quantity.
#
#  Signed wall shear stress ("save u_tau with sign = .true."): u_tau is then signed and measures
#  only the component of the wall traction along the free stream direction f, projected onto the wall:
#     tau = tau_vector . t3,   t3 = (f - (f.n) n) / |f - (f.n) n|
#  so |tau| <= |tau_vector|. With --signed the script checks
#     |tau| = rho u_tau^2,  tau_i = rho |u_tau_vector| u_tau_i,  |tau_vector| >= |tau|
#  and, with --order N and --aoa THETA PHI, rebuilds tau from tau_vector and the wall normal n,
#  which is computed from the node coordinates (x, y, z) of the file (see below).
#
#  Wall normal from the surface mesh: the file must be exported at the order of the solution
#  (no "output order"), so the nodes are the Gauss-Legendre points of the faces; they are stored
#  face after face, (N+1)x(N+1) nodes per face, the first index running fastest. At each face
#     x_xi  = D x(.,j),   x_eta = D x(i,.),   n = x_xi x x_eta / |x_xi x x_eta|
#  with D the spectral differentiation matrix of the nodes. Only (f.n)^2 enters, so the
#  orientation of n is irrelevant.
#
#  Usage: python3 check_wall_shear.py FILE.tec [TOLERANCE] [--signed] [--order N --aoa THETA PHI]
#
import math
import sys

REQUIRED = ["u_tau", "u_tau_x", "u_tau_y", "u_tau_z", "tau", "tau_x", "tau_y", "tau_z", "rho"]
if "--order" in sys.argv:
    REQUIRED = REQUIRED + ["x", "y", "z"]

args = sys.argv[1:]
signed = "--signed" in args
if signed:
    args.remove("--signed")
order, aoa = None, None
if "--order" in args:
    i = args.index("--order")
    order = int(args[i + 1])
    del args[i:i + 2]
if "--aoa" in args:
    i = args.index("--aoa")
    aoa = (float(args[i + 1]), float(args[i + 2]))
    del args[i:i + 3]
if (order is None) != (aoa is None):
    sys.exit("--order and --aoa must be given together")
fileName = args[0]
tol = float(args[1]) if len(args) > 1 else 1.0e-4
tol_normal = 1.0e-6     # the normal is rebuilt from the nodes: it matches the solver one to ~1e-8, while ignoring the projection gives ~1e-3

variables, rows, zones = None, [], 0
with open(fileName) as f:
    for line in f:
        if line.startswith("VARIABLES"):
            variables = [v.strip().strip('"') for v in line.split("=", 1)[1].split(",")]
        elif line.startswith("ZONE"):
            zones += 1
        elif zones == 1 and variables is not None:
            values = line.split()
            if len(values) == len(variables):      # skips the connectivity lines
                rows.append([float(v) for v in values])

if variables is None:
    sys.exit(f"FAILED [{fileName}]: missing VARIABLES header")
missing = [v for v in REQUIRED if v not in variables]
if missing:
    sys.exit(f"FAILED [{fileName}]: variables not found: {missing}\n  in: {variables}")
if not rows:
    sys.exit(f"FAILED [{fileName}]: no point data found")
if not all(math.isfinite(v) for row in rows for v in row):
    sys.exit(f"FAILED [{fileName}]: NaN or infinite values found")

col = {v: variables.index(v) for v in REQUIRED}
get = lambda row, name: row[col[name]]

norm = lambda r, names: math.sqrt(sum(get(r, c) ** 2 for c in names))
if signed:
    # u_tau is signed and only measures the free stream component: |u_tau| <= |u_tau_vector|,
    # |tau| <= |tau_vector|; the identities that do not involve the projection still hold
    checks = {
        "|tau| = rho u_tau^2":
            [(abs(get(r, "tau")), get(r, "rho") * get(r, "u_tau") ** 2) for r in rows],
    }
    inequalities = {
        "u_tau <= |u_tau_vector|":
            [(get(r, "u_tau"), norm(r, ("u_tau_x", "u_tau_y", "u_tau_z"))) for r in rows],
        "|tau| <= |tau_vector|":
            [(abs(get(r, "tau")), norm(r, ("tau_x", "tau_y", "tau_z"))) for r in rows],
    }
else:
    checks = {
        "|u_tau_vector| = u_tau":
            [(norm(r, ("u_tau_x", "u_tau_y", "u_tau_z")), get(r, "u_tau")) for r in rows],
        "tau = rho u_tau^2":
            [(get(r, "tau"), get(r, "rho") * get(r, "u_tau") ** 2) for r in rows],
        "|tau_vector| = tau":
            [(norm(r, ("tau_x", "tau_y", "tau_z")), get(r, "tau")) for r in rows],
    }
    inequalities = {}
for comp in "xyz":
    checks[f"tau_{comp} = rho |u_tau_vector| u_tau_{comp}"] = \
        [(get(r, f"tau_{comp}"), get(r, "rho") * norm(r, ("u_tau_x", "u_tau_y", "u_tau_z")) * get(r, f"u_tau_{comp}"))
         for r in rows]

failed = False
for name, pairs in checks.items():
    scale = max(abs(b) for _, b in pairs)
    diff = max(abs(a - b) for a, b in pairs)
    rel = diff / scale if scale > 0.0 else diff
    ok = rel <= tol
    failed = failed or not ok
    print(f"   {name:<28s}: max rel diff = {rel:.3e}  [{'OK' if ok else 'FAILED'}]")

for name, pairs in inequalities.items():
    scale = max(abs(b) for _, b in pairs)
    excess = max(a - b for a, b in pairs) / scale if scale > 0.0 else 0.0
    ok = excess <= tol
    failed = failed or not ok
    print(f"   {name:<28s}: max excess = {excess:.3e}  [{'OK' if ok else 'FAILED'}]")

if order is not None:
    # --- wall normal from the nodes of the file and tau = tau_vector . t3 -------------------
    n1 = order + 1
    if len(rows) % (n1 * n1) != 0:
        sys.exit(f"FAILED [{fileName}]: {len(rows)} points are not a whole number of {n1}x{n1} faces "
                 "(export at the order of the solution)")

    def gauss_nodes(n):          # Gauss-Legendre points in (-1, 1): roots of P_n
        def legendre(x):
            p0, p1 = 1.0, x
            for k in range(2, n + 1):
                p0, p1 = p1, ((2 * k - 1) * x * p1 - (k - 1) * p0) / k
            return p1, (n * (x * p1 - p0)) / (x * x - 1.0)
        xs = []
        for j in range(n):
            x = -math.cos(math.pi * (j + 0.75) / (n + 0.5))
            for _ in range(100):
                p, dp = legendre(x)
                dx = p / dp
                x -= dx
                if abs(dx) < 1.0e-15:
                    break
            xs.append(x)
        return xs

    xi = gauss_nodes(n1)
    bw = [1.0 / math.prod(xi[i] - xi[k] for k in range(n1) if k != i) for i in range(n1)]
    D = [[(bw[j] / bw[i]) / (xi[i] - xi[j]) if i != j else 0.0 for j in range(n1)] for i in range(n1)]
    for i in range(n1):
        D[i][i] = -sum(D[i][j] for j in range(n1) if j != i)

    theta, phi = (math.radians(a) for a in aoa)
    f = (math.cos(theta) * math.cos(phi), math.sin(theta) * math.cos(phi), math.sin(phi))
    cross = lambda a, b: (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])

    tau_max = max(abs(get(r, "tau")) for r in rows)
    worst, used, skipped = 0.0, 0, 0
    for face in range(len(rows) // (n1 * n1)):
        X = [[[get(rows[face * n1 * n1 + j * n1 + i], c) for c in ("x", "y", "z")] for j in range(n1)] for i in range(n1)]
        for i in range(n1):
            for j in range(n1):
                xxi = [sum(D[i][k] * X[k][j][d] for k in range(n1)) for d in range(3)]
                xet = [sum(D[j][k] * X[i][k][d] for k in range(n1)) for d in range(3)]
                n = cross(xxi, xet)
                nn = math.sqrt(sum(c * c for c in n))
                n = [c / nn for c in n]
                ft2 = 1.0 - sum(a * b for a, b in zip(f, n)) ** 2          # |f - (f.n) n|^2
                r = rows[face * n1 * n1 + j * n1 + i]
                if ft2 < 1.0e-3:           # free stream (almost) perpendicular to the wall: t3 undefined
                    skipped += 1
                    continue
                tau_s = sum(get(r, f"tau_{c}") * fc for c, fc in zip("xyz", f)) / math.sqrt(ft2)
                worst = max(worst, abs(tau_s - get(r, "tau")))
                used += 1
    rel = worst / tau_max if tau_max > 0.0 else worst
    ok = used > 0 and rel <= tol_normal
    failed = failed or not ok
    print(f"   tau = tau_vector . t3 (n from nodes): max rel diff = {rel:.3e}  "
          f"({used} points, {skipped} skipped)  [{'OK' if ok else 'FAILED'}]")

# The check is meaningless if the wall shear is zero everywhere
for name in ("u_tau", "tau"):
    vmax = max(get(r, name) for r in rows)
    if not vmax > 0.0:
        print(f"   {name} is zero at every point  [FAILED]")
        failed = True

if failed:
    sys.exit(f"FAILED [{fileName}]: wall shear stress variables are inconsistent (tolerance {tol:.1e})")
print(f"OK [{fileName}]: {len(rows)} points, wall shear stress variables consistent (tolerance {tol:.1e})")
